const legacyCreateCourse=window.openCourseCreate;
const legacyOpenModal=window.openAI;
const legacyCloseModal=window.closeAI;
const removeCreateFooters=()=>{const modal=document.getElementById('modal');if(modal)modal.querySelectorAll('.create-footer').forEach(el=>el.remove())};
window.openAI=function(title){removeCreateFooters();return legacyOpenModal(title)};
window.closeAI=function(){removeCreateFooters();if(legacyCloseModal)legacyCloseModal();const modal=document.getElementById('modal'),bg=document.getElementById('modalBg');if(modal)modal.className='modal';if(bg)bg.className='modal-bg';document.body.classList.remove('modal-lock');document.documentElement.classList.remove('modal-lock')};
const modalCloseButton=document.getElementById('modalClose');
if(modalCloseButton)modalCloseButton.onclick=window.closeAI;
window.openCourseCreate=function(){
  removeCreateFooters();
  const modal=document.getElementById('modal');
  legacyCreateCourse();
  const stream=document.getElementById('stream'),form=document.getElementById('createForm'),actions=form&&form.querySelector('.form-actions');
  if(!modal||!stream||!form||!actions)return;
  actions.classList.add('create-footer');
  actions.querySelectorAll('button[type="submit"]').forEach(btn=>btn.setAttribute('form','createForm'));
  modal.appendChild(actions);
  stream.classList.add('create-scroll');
};
