const prepBlock=(id,title,label,body,source,risk)=>'<article class="prep-panel prep-block" id="prep-'+id+'"><div class="prep-block-head"><div><h2>'+title+' <small>'+label+'</small></h2></div><div class="prep-block-actions"><button class="btn secondary" onclick="prepAction(\''+id+'\',\'已接受建议\')">接受</button><button class="btn secondary" onclick="prepAction(\''+id+'\',\'已打开重写\')">重写</button></div></div>'+body+'<div class="prep-source"><span>⌁ '+source+'</span><a href="#prep-source" onclick="prepContext(\''+source+'\');return false">查看教材上下文 →</a></div>'+(risk?'<div class="prep-risk">! '+risk+'</div>':'')+'</article>';
