style.textContent+=' .prep-edit-overlay{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;padding:20px;background:rgba(18,45,49,.38)}.prep-edit-modal{width:min(900px,96vw);max-height:min(680px,90vh);display:flex;flex-direction:column;background:#fff;border:1px solid #d8ebe7;border-radius:16px;box-shadow:0 24px 70px rgba(15,59,61,.25);overflow:hidden}.prep-edit-head{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid #e8f1ef}.prep-edit-head h3{margin:0;font:700 18px Georgia,"Microsoft YaHei",serif;color:#173f40}.prep-edit-close{border:0;background:transparent;color:#78918e;font-size:22px;cursor:pointer}.prep-edit-body{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(260px,.92fr);gap:0;min-height:0;overflow:hidden}.prep-edit-pane{padding:16px 20px;min-width:0}.prep-edit-pane+.prep-edit-pane{border-left:1px solid #e8f1ef;background:#f7fbfa}.prep-edit-pane label{display:block;margin-bottom:8px;font-size:11px;font-weight:700;color:#577471}.prep-edit-textarea{width:100%;min-height:300px;resize:vertical;border:1px solid #cfe5e0;border-radius:10px;padding:12px;color:#315455;font:13px/1.7 system-ui,"Microsoft YaHei",sans-serif;box-sizing:border-box;outline:none}.prep-edit-textarea:focus{border-color:#30ad9b;box-shadow:0 0 0 3px #ddf4ef}.prep-edit-source{height:300px;overflow:auto;padding:12px 14px;border:1px solid #d8e9e5;border-radius:10px;background:#122f35;color:#d8f2ed;font:12px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap}.prep-edit-foot{display:flex;justify-content:flex-end;gap:8px;padding:14px 20px;border-top:1px solid #e8f1ef}@media(max-width:700px){.prep-edit-body{grid-template-columns:1fr}.prep-edit-pane+.prep-edit-pane{border-left:0;border-top:1px solid #e8f1ef}.prep-edit-textarea,.prep-edit-source{min-height:190px;height:190px}}';
