window.prepEdit=function(id){
  const field=document.getElementById('prep-'+id); if(!field)return;
  const title=field.querySelector('h2')?.childNodes[0]?.textContent?.trim()||'备课内容';
  const content=field.querySelector('.prep-field-content');
  const schemas={
    basic:[['开课系部','智能科学与技术系'],['教师姓名','张寒'],['课程名称','离散数学'],['授课专业和班级','智能25-1、25-2'],['教学内容','第一章 集合论基础 · 第二节 关系'],['授课学时','6 学时']],
    objective:[['教学目的','掌握关系的基本概念及其性质；掌握五类关系、关系的幂与闭包、等价关系和偏序关系。']],
    focus:[['教学重点','关系的基本概念及性质；五类关系性质；关系的幂、周期性和闭包；等价关系与偏序关系。'],['教学难点','区分五类关系性质，理解关系闭包，掌握 Hasse 图绘制规则。']],
    method:[['习题解析','通过习题解析巩固关系性质的判断。'],['课堂讨论','比较等价关系与偏序关系的异同。'],['作业反馈','通过批改作业发现 Hasse 图绘制中的共性错误。']],
    'method-tools':[['教学方法','课堂讲授'],['教学手段','课堂讲授、多媒体教学'],['教学设计方式','提问、板书推导、精讲多练。']],
    feature:[['课程特色','以学生为主体，强调理解概念、性质、定理和推理过程，坚持少而精、精讲多练。']],
    ideology:[['课程思政','从基本知识点出发，培养学生的科学思维和严谨求实的基本能力。']],
    summary:[['本章小结','本节介绍关系的基本概念及其性质、关系的幂、周期性和闭包，以及等价关系、等价类、划分、商集、偏序关系和 Hasse 图。']],
    homework:[['作业题 1','给出一个关系，判断它是否为等价关系、是否为偏序关系。'],['作业题 2','根据给定偏序关系绘制 Hasse 图。']]
  };
  const schema=schemas[id]||[['内容','']];
  let values; try{values=JSON.parse(field.dataset.prepValues||'null')}catch{values=null}
  if(!Array.isArray(values)){values=schema.map(x=>x[1]);if(schema.length===1&&content)values[0]=content.innerText.trim();}
  const sources={basic:'课程基础信息 · 教学日历',objective:'教材第 1 章第 2 节“关系”· 教学目标',focus:'教材第 1 章第 2 节“关系”· 关系性质与偏序关系',method:'教师教案模板 · 解决方法','method-tools':'教师教案模板 · 教学方法和手段',feature:'教师教案模板 · 课程特色',ideology:'教师教案模板 · 课程思政',summary:'教师教案模板 · 本章小结',homework:'教师教案模板 · 思考与作业题'};
  const excerpts={basic:'【课程基础信息】\n本模块内容来自已审核大纲和教学日历，不对应教材中的独立原文切片。',objective:'【教材原文切片 · 第一章 集合论基础 / 第二节 关系】\n\n关系是集合之间的一种对应。设 A、B 为集合，A 到 B 的关系 R 是笛卡尔积 A×B 的一个子集；当 A=B 时，称 R 为 A 上的关系。关系可以用有序对集合、关系矩阵或关系图表示。\n\n本节要求掌握自反、反自反、对称、反对称和传递等基本性质，并能根据定义判断给定关系是否满足这些性质。进一步学习关系的幂、关系的闭包，以及等价关系、等价类、划分、商集和偏序关系。\n\n偏序关系的表示重点是 Hasse 图：在保持可达关系的前提下，省略自反边和传递边，突出元素之间的覆盖关系。',focus:'【教材原文切片 · 第一章 集合论基础 / 第二节 关系】\n\n【关系性质的判断】\n判断一个关系是否具有某种性质，应回到定义逐项检查：若对任意 x∈A 都有 xRx，则称 R 具有自反性；若 xRy 必有 yRx，则称 R 具有对称性；若 xRy 且 yRx 必有 x=y，则称 R 具有反对称性；若 xRy、yRz 能推出 xRz，则称 R 具有传递性。\n\n例如，在集合 {1,2,3} 上，关系 R={(1,1),(2,2),(3,3),(1,2),(2,1)} 是自反且对称的，但不是传递关系时，需要寻找满足 1R2、2R3 而 1R3 不成立的反例。\n\n【关系运算与性质】\n对关系进行并、交、差、逆和复合运算后，新的关系可能保留原有性质，也可能改变性质。教材表 7.2 对 R₁⁻¹、R₁∩R₂、R₁∪R₂、R₁−R₂、R₁∘R₂ 的自反性、反自反性、对称性、反对称性和传递性进行了归纳。\n\n【偏序关系】\n偏序关系可用 Hasse 图表示，绘图时省略自反边和传递边，只保留覆盖关系。',method:'【教案模板依据】\n本模块依据教师教案模板中的“解决方法”字段生成，暂无直接教材出处。', 'method-tools':'【教案模板依据】\n本模块依据教师教案模板中的“教学方法和手段”字段生成，暂无直接教材出处。',feature:'【教案模板依据】\n本模块依据教师教案模板中的“课程特色”字段生成，暂无直接教材出处。',ideology:'【教案模板依据】\n本模块依据教师教案模板中的“课程思政”字段生成，暂无直接教材出处。',summary:'【教案模板依据】\n本模块依据教师教案模板中的“本章小结”字段生成，暂无直接教材出处。',homework:'【教案模板依据】\n本模块依据教师教案模板中的“思考或作业题”字段生成，暂无直接教材出处。'};
  const hasTextbookSource=id==='objective'||id==='focus';
  const form=schema.map((x,i)=>'<div class="prep-edit-field"><label for="prepEditInput'+i+'">'+x[0]+'</label><textarea id="prepEditInput'+i+'" class="prep-edit-textarea">'+escapeHtml(values[i]||'')+'</textarea></div>').join('');
  const overlay=document.createElement('div'); overlay.className='prep-edit-overlay'; overlay.id='prepEditModal';
  const sourcePane=hasTextbookSource?'<div class="prep-edit-pane"><div class="prep-edit-kicker">教材原文切片</div><div class="prep-edit-source"><b>'+sources[id]+'</b>\n\n'+excerpts[id]+'</div></div>':'';
  overlay.innerHTML='<div class="prep-edit-modal prep-edit-modal-'+id+'" role="dialog" aria-modal="true" aria-label="编辑'+title+'"><div class="prep-edit-head"><h3>编辑 · '+title+'</h3><button class="prep-edit-close" aria-label="关闭编辑弹窗">×</button></div><div class="prep-edit-body'+(hasTextbookSource?'':' prep-edit-body-single')+'"><div class="prep-edit-pane">'+form+'</div>'+sourcePane+'</div><div class="prep-edit-foot"><button class="btn secondary" data-prep-edit-cancel>取消</button><button class="btn primary" data-prep-edit-save>保存修改</button></div></div>';
  document.body.appendChild(overlay);
  const close=()=>overlay.remove(); overlay.querySelector('.prep-edit-close').onclick=close; overlay.querySelector('[data-prep-edit-cancel]').onclick=close;
  overlay.querySelector('[data-prep-edit-save]').onclick=()=>{const next=schema.map((_,i)=>overlay.querySelector('#prepEditInput'+i)?.value.trim()||'');field.dataset.prepValues=JSON.stringify(next);if(content)content.innerHTML=next.map((v,i)=>'<p><b>'+escapeHtml(schema[i][0])+'：</b>'+escapeHtml(v).replace(/\n/g,'<br>')+'</p>').join('');close();prepAction(id,'已保存修改');};
  overlay.querySelector('.prep-edit-textarea')?.focus();
};
window.prepNotice=function(title,body,buttons){const overlay=document.createElement('div');overlay.className='prep-edit-overlay';overlay.id='prepEditModal';overlay.innerHTML='<div class="prep-edit-modal prep-notice-modal" role="dialog" aria-modal="true"><div class="prep-edit-head"><h3>'+title+'</h3><button class="prep-edit-close" aria-label="关闭">×</button></div><div class="prep-edit-pane"><p style="margin:0;color:#486866;line-height:1.7">'+body+'</p><div class="prep-notice-actions">'+(buttons||'<button class="btn primary" data-close>知道了</button>')+'</div></div></div>';document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelector('.prep-edit-close').onclick=close;overlay.querySelector('[data-close]')?.addEventListener('click',close);return {overlay,close};};
window.prepSaveDraft=function(){const data={chapter:document.querySelector('.prep-outline h3')?.textContent||'',fields:{}};document.querySelectorAll('.preparation-page .prep-field-content').forEach(el=>{const section=el.closest('.prep-field');if(section)data.fields[section.id]=el.innerHTML;});localStorage.setItem('prepDraftV1',JSON.stringify(data));prepNotice('草稿已保存','本节备课草稿已保存，下次进入备课工作台时会自动恢复。');};
